beforeSaveCustomScript:
if (websiteReferenceId != null && websiteReferenceId != '') {
    $contact = ifThenElse(websiteContactName != null && websiteContactName != '', websiteContactName, 'Segnalazione');
    $sportello = ifThenElse(sportelloDisplayName != null && sportelloDisplayName != '', sportelloDisplayName, ifThenElse(type == 'SportelloDigitale', 'Sp. Digitale', ifThenElse(type == 'SportelloLegale', 'Sp. Legale', 'Sportello')));
    $dateLabel = ifThenElse(createdAt != null && createdAt != '', datetime\format(createdAt, 'Europe/Rome', 'DD/MM/YYYY'), datetime\format(datetime\now(), 'Europe/Rome', 'DD/MM/YYYY'));
    name = string\concatenate($contact, ' | ', $dateLabel, ' | ', $sportello);
}
